public int Candy(int[] ratings) {
    int n = ratings.Length;
    var candies = new int[n];
    Array.Fill(candies, 1);                                // .NET Standard 2.1; otherwise a loop
    for (int i = 1; i < n; i++)                            // left rules
        if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
    for (int i = n - 2; i >= 0; i--)                       // right rules, keeping the left ones
        if (ratings[i] > ratings[i + 1]) candies[i] = Math.Max(candies[i], candies[i + 1] + 1);
    return candies.Sum();                                  // LINQ; in hot code, your own loop
}

