// #455: child i needs a cookie of size ≥ g[i]; feed as many children as possible
public int FindContentChildren(int[] g, int[] s) {
    Array.Sort(g); Array.Sort(s);
    int child = 0;
    foreach (int cookie in s)                                  // from the smallest cookie up
        if (child < g.Length && cookie >= g[child]) child++;   // least demanding child gets the first fit
    return child;
}

